{
  "technical_and_design_decisions": [
    "For U1: In Java, create a new transactional context object per transaction to ensure thread-safety, accepting the performance trade-off for safety. In Node.js, the context is already passed as the first parameter, so no changes are needed there.",
    "For U2/U3: Move the contents of `protos/utils` to a new package `protoutils` and update all import references throughout the codebase.",
    "For U4: Backport the Kafka health check feature from the master branch to the Fabric 1.4 LTS branch, adapting it as needed for compatibility.",
    "For U5: Implement access control checks based on the actual chaincode operations (reads vs. writes) during invocation, rather than at the chaincode invocation level.",
    "For U6: Add a new configuration option for the peer (e.g., `core.peer.externalEndpoint`) to explicitly set the advertised endpoint for service discovery.",
    "For U7: Extend the operations service to include the peer's/orderer's version information in its HTTP response.",
    "For U8: Rewrite the sample chaincode and applications in Go to use idiomatic Go patterns (e.g., error handling, structure, and naming conventions)."
  ],
  "assumptions": [
    "The development environment and necessary tools (e.g., Docker, Go, Node.js, Java) are already set up and functional.",
    "The Hyperledger Fabric codebase is accessible and in a state ready for these changes.",
    "Each activity can be developed and tested independently without major dependencies on other ongoing work.",
    "Testing will be performed as part of each activity, but test effort is included in the estimate.",
    "The developer has sufficient knowledge of the Hyperledger Fabric codebase and the relevant languages (Go, Java, Node.js) to implement these changes efficiently.",
    "The changes are additive and do not require significant architectural redesigns beyond the scope described.",
    "For U5, the chaincode execution environment can be instrumented to track read/write operations without excessive overhead."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement transactional context for chaincode",
      "activity_description": "For Java chaincode, create a transactional context object per transaction to ensure thread-safety, and update the chaincode shim accordingly. For Node.js, verify and document that the context is already passed as the first parameter (no code changes required).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Refactor protos/utils to protoutils",
      "activity_description": "Move the code from the `protos/utils` package to a new `protoutils` package, update all import paths across the codebase, and ensure all tests pass.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Backport Kafka health checks to Fabric 1.4 LTS",
      "activity_description": "Identify and merge the Kafka health check commits from the master branch into the Fabric 1.4 LTS branch, resolving any conflicts and adapting the changes for compatibility.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement operation-based access control for chaincode invoke",
      "activity_description": "Modify the chaincode invocation logic to track read/write operations (Gets vs. Puts) and enforce access control based on the user's channel permissions (Reader vs. Writer).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "Add peer external endpoint configuration for service discovery",
      "activity_description": "Add a new peer configuration option to explicitly set the external endpoint advertised to SDK users, and update the service discovery module to use this endpoint.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Expose version in operations service",
      "activity_description": "Extend the operations service to include the peer's/orderer's version information in its HTTP response, enabling operators to check upgrade readiness.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Rewrite samples in idiomatic Go",
      "activity_description": "Review and rewrite the existing Go samples (chaincode and applications) to follow Go idioms and best practices, improving readability and maintainability for Go developers.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 27
  }
}

